function feynmanNotes(opts){
  opts=opts||{};
  var topic=(opts.topic||'概念').trim()||'概念';
  var points=String(opts.points||'').split(/[\n,，;；]+/).map(function(s){return s.trim();}).filter(Boolean);
  var L=[];
  L.push('# 费曼笔记 · '+topic);
  L.push('');
  L.push('## 1. 用最简单的语言解释');
  L.push('- ');
  L.push('');
  L.push('## 2. 关键要点');
  if(points.length){ for(var i=0;i<points.length;i++) L.push('- '+points[i]); }
  else { L.push('- （列出构成这个概念的关键要素）'); }
  L.push('');
  L.push('## 3. 打个比方（类比）');
  L.push('- （用一个日常事物类比它）');
  L.push('');
  L.push('## 4. 卡住的地方 / 还要查的');
  L.push('- （写不清楚的地方，就是还没真正懂的地方）');
  return L.join('\n');
}

var EXPORTS={feynmanNotes:feynmanNotes};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FeynmanForgePure = EXPORTS; }
